{
  "case_id": "C06",
  "audience": "General public with secondary-school science literacy",
  "target_duration_s": 60,
  "beats": [
    {
      "beat": "The idea",
      "narration": "Gut bacteria from a lean mouse, moved into a mouse born with no gut bacteria at all. Does the recipient stay leaner? That is the experiment.",
      "on_screen": "Simple animation: bacteria transferred from a lean donor mouse into a germ-free recipient",
      "claim_refs": ["Background", "Abstract"]
    },
    {
      "beat": "The headline result",
      "narration": "The paper's main text says yes. After eight weeks, recipients of lean-donor microbes gained twenty-four percent less fat than recipients of obese-donor microbes. Twenty mice per group, p equals 0.003.",
      "on_screen": "Bar chart: -24% fat mass, p = 0.003, n = 20 per group",
      "claim_refs": ["Abstract", "Results"]
    },
    {
      "beat": "One donor pair",
      "narration": "But that number comes from a single pair of donors. Three more pairs are reported in the supplement, and they disagree: minus six percent, plus three percent, minus nineteen percent. Pool all four and the effect is minus eleven percent, with a range that still includes no effect at all.",
      "on_screen": "Four bars side by side, wildly different; pooled estimate with a confidence interval crossing zero",
      "claim_refs": ["S3"]
    },
    {
      "beat": "The missing control",
      "narration": "The supplement holds a second surprise. In an arm where every mouse was fed the same amount of food, the difference nearly vanished: minus four percent, not significant. So much of the original effect looks like how much the mice ate, not which microbes they carried.",
      "on_screen": "Food bowls equalised; the gap shrinks to -4%, labelled 'not significant'",
      "claim_refs": ["S2", "Methods"]
    },
    {
      "beat": "What to take away",
      "narration": "Gut microbes may still shape body fat. This study just doesn't show it. When the headline rests on one donor pair, and the control that undercuts it sits in the supplement, the supplement is where the science is.",
      "on_screen": "Text card: 'Check the supplement.'",
      "claim_refs": ["S3", "S2", "Conclusion", "Discussion"]
    }
  ]
}
